def load_navigation_channel_seed() -> dict[str, Any]:
    compressed = ''.join(COMPRESSED_PAYLOAD).encode('ascii')
    raw = zlib.decompress(base64.b64decode(compressed)).decode('utf-8')
    return json.loads(raw)
